public class Solution {
    public static class P {
        private int v;
        public P(int start) { v = start; }
        public void bump() { v = v + 1; }
        public int get() { return v; }
    }
    public static int demo() {
        P x = new P(10);
        P y = x;
        y.bump();
        x.bump();
        y.bump();
        return x.get() * 10 + y.get();
    }
}
